// Иллюстративные логиты для следующего токена после "The capital of France is"
const tokens = [" Paris", " a", " the", " located", " Lyon"];
const logits = [4.0, 3.0, 2.5, 1.5, 0.5];

function softmax(xs) {
  const m = Math.max(...xs);                 // вычитаем максимум ради численной устойчивости
  const exps = xs.map(x => Math.exp(x - m));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);             // сумма вероятностей = 1
}

function withTemperature(logits, T) {
  return softmax(logits.map(z => z / T));    // вот и весь механизм temperature
}

for (const T of [0.2, 0.5, 1.0, 2.0]) {
  const p = withTemperature(logits, T);
  console.log("T=" + T, p.map(x => (x * 100).toFixed(1) + "%").join("  "));
}
// T=0.2 99.3%  0.7%  0.1%  0.0%  0.0%
// T=0.5 83.8%  11.3%  4.2%  0.6%  0.1%
// T=1 58.7%  21.6%  13.1%  4.8%  1.8%
// T=2 39.4%  23.9%  18.6%  11.3%  6.8%

// Оставить самый короткий верхний набор, чья масса достигла p (потом перенормировать)
function topP(probs, p) {
  const order = probs.map((pr, i) => [pr, i]).sort((a, b) => b[0] - a[0]);
  const kept = [];
  let mass = 0;
  for (const [pr, i] of order) {
    kept.push(i);
    mass += pr;
    if (mass >= p) break;
  }
  return kept.length;
}
function topKMass(probs, k) {
  return [...probs].sort((a, b) => b - a).slice(0, k).reduce((a, b) => a + b, 0);
}

// Иллюстративные логиты, игрушечный словарь из 50 токенов
const confident = [9, ...Array.from({ length: 49 }, (_, i) => 3 - i * 0.05)];
const unsure = Array.from({ length: 50 }, (_, i) => 3 - i * 0.03);

for (const [name, logits] of [["confident", confident], ["unsure", unsure]]) {
  const probs = softmax(logits); // softmax из примера выше
  console.log(name, "top_p=0.9 keeps", topP(probs, 0.9),
    "| top_k=5 covers", (topKMass(probs, 5) * 100).toFixed(1) + "%");
}
// confident top_p=0.9 keeps 1 | top_k=5 covers 96.4%
// unsure top_p=0.9 keeps 41 | top_k=5 covers 17.9%

