// Имитация float32, как на GPU: Math.fround округляет каждый промежуточный результат до 32 бит
const f = Math.fround;
let seed = 42;
const rand = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648) * 2 - 1;
const xs = Array.from({ length: 4096 }, () => f(rand()));

// Порядок A: складываем слева направо
let a = 0;
for (const x of xs) a = f(a + x);

// Порядок B: 64 куска по 64, сначала частичные суммы, потом их сумма (как параллельная редукция)
const partial = [];
for (let c = 0; c < 64; c++) {
  let s = 0;
  for (let i = c * 64; i < (c + 1) * 64; i++) s = f(s + xs[i]);
  partial.push(s);
}
let b = 0;
for (const s of partial) b = f(b + s);

console.log(a, b, a === b);
